import sys
from pptx import Presentation
from pptx.enum.shapes import MSO_SHAPE_TYPE

def inspect(pptx_path):
    prs = Presentation(pptx_path)
    for i, slide in enumerate(prs.slides):
        print(f"Slide {i}:")
        for shape in slide.shapes:
            if not shape.has_text_frame:
                continue
            text = shape.text_frame.text.strip()
            if not text:
                continue

            is_placeholder = shape.is_placeholder
            ph_type = shape.placeholder_format.type if is_placeholder else "None"

            print(f"  Shape (Type: {shape.shape_type}, Placeholder: {is_placeholder}, PH Type: {ph_type})")
            print(f"    Text: {text[:50]}...")
            print(f"    Left: {shape.left}, Top: {shape.top}, Width: {shape.width}, Height: {shape.height}")

if __name__ == "__main__":
    inspect(sys.argv[1])

